// Retired. Academic covers are generated by the Cloudflare Worker
// (`/api/cover-generate`) with the Workers AI binding. This function must not call Monica.

const cors = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Content-Type": "application/json",
};

Deno.serve((req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: cors });
  return new Response(
    JSON.stringify({
      error: "Cover generation moved to the kidsmybook.com Worker (Workers AI).",
      code: "not_configured",
    }),
    { status: 410, headers: cors },
  );
});
